using Shouldly;
using Winpepper.Models;
using Xunit;

namespace Winpepper.Models.Tests;

public class ModelRegistryInstallDirTests
{
    [Fact]
    public void InstallDirFor_DefaultAsr_MatchesLegacyParakeetLeaf()
    {
        var registry = new ModelRegistry();
        var root = Path.Combine("C:", "root", "models");

        var dir = registry.InstallDirFor(root, ModelRegistry.DefaultAsrName, ModelKind.Asr);

        dir.ShouldBe(Path.Combine(root, "parakeet-tdt-0.6b-v3"));
    }

    [Fact]
    public void InstallDirFor_NullName_FallsBackToDefaultAsr()
    {
        var registry = new ModelRegistry();
        var root = Path.Combine("C:", "root", "models");

        var dir = registry.InstallDirFor(root, null, ModelKind.Asr);

        dir.ShouldBe(Path.Combine(root, "parakeet-tdt-0.6b-v3"));
    }

    [Fact]
    public void InstallDirFor_UnknownName_FallsBackToDefaultAsr()
    {
        var registry = new ModelRegistry();
        var root = Path.Combine("C:", "root", "models");

        var dir = registry.InstallDirFor(root, "no-such-model", ModelKind.Asr);

        dir.ShouldBe(Path.Combine(root, "parakeet-tdt-0.6b-v3"));
    }

    [Fact]
    public void InstallDirFor_CleanupDefault_UsesCleanupInstallDirRelative()
    {
        var registry = new ModelRegistry();
        var root = Path.Combine("C:", "root", "models");

        var dir = registry.InstallDirFor(root, ModelRegistry.DefaultCleanupName, ModelKind.Cleanup);

        dir.ShouldBe(Path.Combine(root, "cleanup", "qwen2.5-0.5b-instruct-q4_k_m"));
    }
}

using System.Formats.Tar;
using System.IO.Compression;
using System.Security.Cryptography;
using Winpepper.Models;
using Xunit;

namespace Winpepper.Models.Tests;

public class ModelDownloaderExtractionTests : IDisposable
{
    private readonly string _root = Directory.CreateTempSubdirectory("wp-dl-").FullName;
    public void Dispose() { try { Directory.Delete(_root, true); } catch { } }

    // Mirrors the SyncProgress helper in ModelDownloaderTests: reports synchronously
    // so assertions can run immediately after DownloadAsync completes.
    private sealed class SyncProgress<T>(Action<T> handler) : IProgress<T>
    {
        public void Report(T value) => handler(value);
    }

    private static (byte[] Bytes, string Sha256) MakeArchiveBytes()
    {
        var tmp = Directory.CreateTempSubdirectory("wp-arc-").FullName;
        try
        {
            var top = Path.Combine(tmp, "toplevel");
            Directory.CreateDirectory(top);
            File.WriteAllText(Path.Combine(top, "contract.json"), "{}");
            using var ms = new MemoryStream();
            using (var gz = new GZipStream(ms, CompressionMode.Compress, leaveOpen: true))
                TarFile.CreateFromDirectory(tmp, gz, includeBaseDirectory: false);
            var bytes = ms.ToArray();
            return (bytes, Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant());
        }
        finally { Directory.Delete(tmp, true); }
    }

    private static ModelDescriptor BuildDescriptor(byte[] bytes, string sha)
    {
        return new ModelDescriptor
        {
            Name = "test-runtime", Kind = ModelKind.Asr, DisplayName = "t",
            InstallDirRelative = "test-runtime",
            Files = new[]
            {
                new ModelFile
                {
                    RelativePath = "native.tar.gz",
                    Url = "https://example.invalid/native.tar.gz",
                    Sha256 = sha, SizeBytes = bytes.Length,
                    ExtractToRelative = "runtime",
                },
            },
        };
    }

    [Fact]
    public async Task Downloaded_archive_with_ExtractToRelative_is_extracted()
    {
        var (bytes, sha) = MakeArchiveBytes();
        var descriptor = BuildDescriptor(bytes, sha);
        // Reuse the existing FakeRangeClient from ModelDownloaderTests.cs
        // (parameterless ctor; bodies registered per-URL via SetBody).
        var fake = new FakeRangeClient();
        fake.SetBody("https://example.invalid/native.tar.gz", bytes);
        var downloader = new ModelDownloader(fake);
        await downloader.DownloadAsync(descriptor, _root,
            new Progress<DownloadProgress>(), CancellationToken.None);

        var modelDir = Path.Combine(_root, "test-runtime");
        Assert.True(File.Exists(Path.Combine(modelDir, "native.tar.gz")));           // archive kept
        Assert.True(File.Exists(Path.Combine(modelDir, "runtime", "toplevel", "contract.json")));
        Assert.Equal(sha, File.ReadAllText(Path.Combine(modelDir, "native.tar.gz.extracted")).Trim());
    }

    [Fact]
    public async Task Extraction_failure_reports_Failed_phase_and_propagates()
    {
        // Garbage bytes (not a valid gzip stream) with a matching descriptor:
        // download and checksum succeed, extraction throws.
        var bytes = new byte[] { 0xDE, 0xAD, 0xBE, 0xEF, 0x00, 0x01, 0x02, 0x03 };
        var sha = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes)).ToLowerInvariant();
        var descriptor = BuildDescriptor(bytes, sha);
        var fake = new FakeRangeClient();
        fake.SetBody("https://example.invalid/native.tar.gz", bytes);
        var downloader = new ModelDownloader(fake);
        var reports = new List<DownloadProgress>();

        var ex = await Record.ExceptionAsync(() => downloader.DownloadAsync(
            descriptor, _root, new SyncProgress<DownloadProgress>(reports.Add), CancellationToken.None));

        Assert.NotNull(ex); // extraction failure must still propagate
        var failed = Assert.Single(reports, r => r.Phase == DownloadPhase.Failed);
        Assert.Equal("native.tar.gz", failed.FileRelativePath);
        Assert.False(string.IsNullOrEmpty(failed.ErrorMessage));
    }

    [Fact]
    public async Task Already_installed_archive_with_missing_extraction_is_healed()
    {
        var (bytes, sha) = MakeArchiveBytes();
        var descriptor = BuildDescriptor(bytes, sha);
        var modelDir = Path.Combine(_root, "test-runtime");
        Directory.CreateDirectory(modelDir);
        await File.WriteAllBytesAsync(Path.Combine(modelDir, "native.tar.gz"), bytes); // pre-installed, never extracted

        var fake = new FakeRangeClient();
        fake.SetBody("https://example.invalid/native.tar.gz", bytes);
        var downloader = new ModelDownloader(fake);
        await downloader.DownloadAsync(descriptor, _root,
            new Progress<DownloadProgress>(), CancellationToken.None);

        Assert.True(File.Exists(Path.Combine(modelDir, "runtime", "toplevel", "contract.json")));
    }
}

using Winpepper.Models.Tests.ViewModels;
using Winpepper.Models.ViewModels;
using Xunit;

namespace Winpepper.Models.Tests;

public class StreamingAutoInstallerTests : IDisposable
{
    private readonly string _root;

    public StreamingAutoInstallerTests()
    {
        _root = Path.Combine(Path.GetTempPath(), $"autoinstall-{Guid.NewGuid():N}");
        Directory.CreateDirectory(_root);
    }

    public void Dispose() { if (Directory.Exists(_root)) Directory.Delete(_root, recursive: true); }

    private StreamingAutoInstaller CreateInstaller(ModelsTabViewModel.IDownloader downloader) =>
        new(new ModelRegistry(), _root, downloader);

    /// <summary>Lay down the full healthy install: every file at its exact
    /// declared size, plus extraction marker and runtime tree for archives.</summary>
    private void WriteHealthyInstall(bool withExtraction = true)
    {
        var d = new ModelRegistry().Find(ModelRegistry.StreamingAsrName)!;
        var modelDir = Path.Combine(_root, d.InstallDirRelative);
        Directory.CreateDirectory(modelDir);
        foreach (var f in d.Files)
        {
            var path = Path.Combine(modelDir, f.RelativePath);
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            using (var fs = File.Create(path)) fs.SetLength(f.SizeBytes); // sparse; exact size
            if (withExtraction && f.ExtractToRelative is { } extractTo)
            {
                File.WriteAllText(path + ".extracted", f.Sha256);
                Directory.CreateDirectory(Path.Combine(modelDir, extractTo));
            }
        }
    }

    [Fact]
    public async Task StartAsync_downloads_the_nemotron_descriptor_when_enabled_and_missing()
    {
        var fake = new FakeDownloader();
        var installer = CreateInstaller(fake);

        await installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);

        Assert.Equal(new[] { ModelRegistry.StreamingAsrName }, fake.DownloadedNames);
        Assert.Equal(StreamingAutoInstallStatus.Installed, installer.Status);
    }

    [Fact]
    public async Task StartAsync_skips_the_download_when_streaming_is_disabled()
    {
        var fake = new FakeDownloader();
        var installer = CreateInstaller(fake);

        await installer.StartAsync(streamingEnabled: false, TestContext.Current.CancellationToken);

        Assert.Empty(fake.DownloadedNames);
        Assert.Equal(StreamingAutoInstallStatus.SkippedStreamingDisabled, installer.Status);
    }

    [Fact]
    public async Task StartAsync_skips_the_download_when_installed_and_extracted()
    {
        // Auto-install runs on EVERY launch, so a healthy install must
        // short-circuit on cheap checks (exact sizes + extraction marker), not
        // re-hash 730 MB per boot. Deep repair stays on the Models card, which
        // always routes through the downloader (commit 1672ae6).
        WriteHealthyInstall();
        var fake = new FakeDownloader();
        var installer = CreateInstaller(fake);

        await installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);

        Assert.Empty(fake.DownloadedNames);
        Assert.Equal(StreamingAutoInstallStatus.Installed, installer.Status);
    }

    [Fact]
    public async Task StartAsync_downloads_when_archive_present_but_extraction_missing()
    {
        // The stuck state commit 1672ae6 healed: archive files complete but
        // extraction failed or the runtime tree was deleted. The auto-install
        // must route through the downloader so EnsureExtracted can heal it.
        WriteHealthyInstall(withExtraction: false);
        var fake = new FakeDownloader();
        var installer = CreateInstaller(fake);

        await installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);

        Assert.Equal(new[] { ModelRegistry.StreamingAsrName }, fake.DownloadedNames);
    }

    [Fact]
    public async Task StartAsync_downloads_when_a_file_is_truncated()
    {
        WriteHealthyInstall();
        var d = new ModelRegistry().Find(ModelRegistry.StreamingAsrName)!;
        var gguf = d.Files.First(f => f.ExtractToRelative is null);
        var path = Path.Combine(_root, d.InstallDirRelative, gguf.RelativePath);
        using (var fs = File.Open(path, FileMode.Open)) fs.SetLength(gguf.SizeBytes - 1);

        var fake = new FakeDownloader();
        var installer = CreateInstaller(fake);
        await installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);

        Assert.Equal(new[] { ModelRegistry.StreamingAsrName }, fake.DownloadedNames);
    }

    [Fact]
    public async Task Concurrent_StartAsync_calls_share_one_download()
    {
        var fake = new BlockingDownloader();
        var installer = CreateInstaller(fake);

        var first = installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);
        await fake.Entered(1);
        var second = installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);

        Assert.Same(first, second); // single flight: one in-flight operation
        fake.Release();
        await first;
        await second;

        Assert.Equal(1, fake.EnteredCount);
        Assert.Equal(StreamingAutoInstallStatus.Installed, installer.Status);
    }

    [Fact]
    public async Task StartAsync_failure_is_captured_not_thrown()
    {
        // A failed background install must leave the app fully functional on
        // the batch path: no exception escapes to the caller, the failure is
        // observable via Status/LastError (for logging and the Models card).
        var installer = CreateInstaller(new ThrowingDownloader());

        await installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);

        Assert.Equal(StreamingAutoInstallStatus.Failed, installer.Status);
        Assert.Contains("boom", installer.LastError);
    }

    [Fact]
    public async Task Failed_attempt_is_retried_by_a_later_StartAsync()
    {
        // Mirrors the v3 retry policy: no background retry loop; the next
        // attempt (next launch, or a manual install) simply runs again.
        var fake = new ThrowingOnceDownloader();
        var installer = CreateInstaller(fake);

        await installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);
        Assert.Equal(StreamingAutoInstallStatus.Failed, installer.Status);

        await installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);
        Assert.Equal(StreamingAutoInstallStatus.Installed, installer.Status);
        Assert.Equal(2, fake.Calls);
    }

    [Fact]
    public async Task StartAsync_raises_StatusChanged_through_the_lifecycle()
    {
        var fake = new FakeDownloader();
        var installer = CreateInstaller(fake);
        var seen = new List<StreamingAutoInstallStatus>();
        installer.StatusChanged += (_, s) => seen.Add(s);

        await installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);

        Assert.Equal(
            new[] { StreamingAutoInstallStatus.Installing, StreamingAutoInstallStatus.Installed },
            seen);
    }

    [Fact]
    public async Task A_throwing_StatusChanged_subscriber_cannot_fault_the_install()
    {
        // StartAsync's contract is never-throw; SetStatus must make that
        // mechanical by containing subscriber exceptions. Without that, a
        // throwing subscriber faults RunAsync (and re-faults inside its catch
        // via SetStatus(Failed)), surfacing an exception to the host's
        // fire-and-forget Task.Run.
        var fake = new FakeDownloader();
        var installer = CreateInstaller(fake);
        installer.StatusChanged += (_, _) => throw new InvalidOperationException("subscriber boom");

        await installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);

        // The install itself completed and the status still updated.
        Assert.Equal(new[] { ModelRegistry.StreamingAsrName }, fake.DownloadedNames);
        Assert.Equal(StreamingAutoInstallStatus.Installed, installer.Status);
        Assert.Null(installer.LastError);
    }

    // Note: the "defer auto-install until onboarding completes" policy lives
    // in the Windows-only AppShell wiring (it reads SettingsStore.Load()
    // before calling StartAsync), so it is not testable from this
    // pure-managed suite.

    [Fact]
    public async Task AutoInstall_and_models_card_download_never_run_concurrently()
    {
        // The auto-install shares the Models page's per-downloader operation
        // gate, so opening the Models page and clicking Install during an
        // auto-install can never write the same model files concurrently.
        var fake = new BlockingDownloader();
        var installer = CreateInstaller(fake);
        var vm = new ModelsTabViewModel(new ModelRegistry(), _root, fake,
            currentAsrName: ModelRegistry.DefaultAsrName,
            currentCleanupName: ModelRegistry.DefaultCleanupName,
            currentStreamingName: ModelRegistry.StreamingAsrName,
            promoteAsr: _ => { }, promoteCleanup: _ => { }, promoteStreaming: _ => { });

        var auto = installer.StartAsync(streamingEnabled: true, TestContext.Current.CancellationToken);
        await fake.Entered(1);
        var card = vm.DownloadSelectedAsync(
            new[] { new ModelRegistry().Find(ModelRegistry.StreamingAsrName)! },
            TestContext.Current.CancellationToken);

        // If the gate were NOT shared, the card download would enter the
        // downloader while the auto-install is still inside it and the overlap
        // flag would latch immediately; give that wrong path a chance to run.
        await Task.WhenAny(fake.Entered(2), Task.Delay(100, TestContext.Current.CancellationToken));

        fake.Release();
        await auto;
        await card;

        Assert.False(fake.SawOverlap, "auto-install and card download overlapped inside the downloader");
        Assert.Equal(2, fake.EnteredCount);
    }

    [Fact]
    public async Task StartAsync_WithSelectedMultilingual_DownloadsTheMultilingualDescriptor()
    {
        // Arranged exactly like the download-when-missing test, but the user's
        // selected primary model is Multilingual: the upgrade-path install must
        // fetch the SELECTED descriptor, not unconditionally the English one.
        var fake = new FakeDownloader();
        var installer = CreateInstaller(fake);

        await installer.StartAsync(streamingEnabled: true,
            selectedModelName: ModelRegistry.MultilingualStreamingAsrName,
            TestContext.Current.CancellationToken);

        Assert.Equal(new[] { ModelRegistry.MultilingualStreamingAsrName }, fake.DownloadedNames);
    }

    [Fact]
    public async Task StartAsync_WithUnknownSelectedName_FallsBackToEnglish()
    {
        // Unknown/bad selected names must never stall the upgrade: fall back
        // to the English default (mirrors ModelRegistry.ResolveOrDefault).
        var fake = new FakeDownloader();
        var installer = CreateInstaller(fake);

        await installer.StartAsync(streamingEnabled: true,
            selectedModelName: "no-such-model",
            TestContext.Current.CancellationToken);

        Assert.Equal(new[] { ModelRegistry.StreamingAsrName }, fake.DownloadedNames);
    }

    private sealed class ThrowingDownloader : ModelsTabViewModel.IDownloader
    {
        public Task DownloadAsync(ModelDescriptor descriptor, string installRoot,
                                  IProgress<DownloadProgress> progress, CancellationToken ct)
            => throw new ModelDownloadException("boom");
    }

    private sealed class ThrowingOnceDownloader : ModelsTabViewModel.IDownloader
    {
        public int Calls { get; private set; }

        public Task DownloadAsync(ModelDescriptor descriptor, string installRoot,
                                  IProgress<DownloadProgress> progress, CancellationToken ct)
        {
            Calls++;
            if (Calls == 1) throw new ModelDownloadException("boom");
            return Task.CompletedTask;
        }
    }

    /// <summary>Every call blocks until <see cref="Release"/>; records entry
    /// count, per-count entry signals, and whether two calls ever overlapped.</summary>
    private sealed class BlockingDownloader : ModelsTabViewModel.IDownloader
    {
        private readonly TaskCompletionSource _release =
            new(TaskCreationOptions.RunContinuationsAsynchronously);
        private readonly object _gate = new();
        private readonly Dictionary<int, TaskCompletionSource> _entered = new();
        private int _enteredCount;
        private int _active;

        public bool SawOverlap { get; private set; }
        public int EnteredCount => Volatile.Read(ref _enteredCount);
        public void Release() => _release.TrySetResult();

        public Task Entered(int count)
        {
            lock (_gate) return EnteredTcs(count).Task;
        }

        private TaskCompletionSource EnteredTcs(int count)
        {
            if (!_entered.TryGetValue(count, out var tcs))
            {
                tcs = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
                _entered[count] = tcs;
            }
            return tcs;
        }

        public async Task DownloadAsync(ModelDescriptor descriptor, string installRoot,
                                        IProgress<DownloadProgress> progress, CancellationToken ct)
        {
            lock (_gate)
            {
                if (Interlocked.Increment(ref _active) > 1) SawOverlap = true;
                _enteredCount++;
                EnteredTcs(_enteredCount).TrySetResult();
            }
            try { await _release.Task.WaitAsync(ct); }
            finally { Interlocked.Decrement(ref _active); }
        }
    }
}

using Winpepper.Models.ViewModels;

namespace Winpepper.Models;

public enum StreamingAutoInstallStatus
{
    NotStarted,
    SkippedStreamingDisabled,
    Installing,
    Installed,
    Failed,
}

/// <summary>
/// First-run auto-install of the Nemotron streaming model + native runtime.
/// The batch ASR model gets its install-on-first-run treatment through the
/// blocking onboarding download step; the streaming model gets the same
/// outcome without blocking anything: the host fires <see cref="StartAsync"/>
/// on every launch, dictation works immediately via the batch path, and
/// streaming activates on the first dictation after the install lands
/// (PipelineHost re-checks installed state per dictation).
///
/// Policies, mirrored from the batch model where they apply:
/// - Retry: transient network retry lives in <see cref="ModelDownloader"/>;
///   beyond that there is no background retry loop — a failed attempt is
///   simply re-run on the next launch or from the Models card.
/// - Failure: never throws. A failed install leaves the app fully functional
///   on batch transcription; the outcome is observable via <see cref="Status"/>
///   / <see cref="LastError"/> for logging and the Models card.
/// - Single flight: one in-flight operation per installer, and the download
///   itself serializes on <see cref="ModelsTabViewModel.SharedOperationGateFor"/>
///   so a Models-card install during an auto-install can never write the same
///   files concurrently (the later run's verify short-circuit keeps it cheap).
/// - Repair: a healthy install short-circuits on cheap checks (exact file
///   sizes + extraction marker) because this runs every launch; a broken
///   extraction fails that check and routes through the downloader, whose
///   EnsureExtracted heal path (commit 1672ae6) repairs it. Deep SHA-256
///   repair stays on the Models card, which always routes through the
///   downloader.
/// </summary>
public sealed class StreamingAutoInstaller
{
    private readonly ModelRegistry _registry;
    private readonly string _installRoot;
    private readonly ModelsTabViewModel.IDownloader _downloader;
    private readonly SemaphoreSlim _operationGate;
    private readonly object _gate = new();
    private Task? _current;
    private StreamingAutoInstallStatus _status = StreamingAutoInstallStatus.NotStarted;

    public StreamingAutoInstaller(
        ModelRegistry registry, string installRoot, ModelsTabViewModel.IDownloader downloader)
    {
        ArgumentNullException.ThrowIfNull(registry);
        ArgumentNullException.ThrowIfNull(installRoot);
        ArgumentNullException.ThrowIfNull(downloader);
        // The English default is the fallback for every run, so its absence is
        // a wiring bug worth failing fast on (the descriptor itself is
        // re-resolved per run to honor the user's selected model).
        _ = registry.Find(ModelRegistry.StreamingAsrName)
            ?? throw new InvalidOperationException(
                $"Streaming model '{ModelRegistry.StreamingAsrName}' is absent from the registry.");
        _registry = registry;
        _installRoot = installRoot;
        _downloader = downloader;
        _operationGate = ModelsTabViewModel.SharedOperationGateFor(downloader);
    }

    public StreamingAutoInstallStatus Status
    {
        get { lock (_gate) return _status; }
    }

    /// <summary>Message of the last failed attempt; null while none failed.</summary>
    public string? LastError { get; private set; }

    public event EventHandler<StreamingAutoInstallStatus>? StatusChanged;

    /// <summary>
    /// Begin (or join) the auto-install. Never throws: the returned task
    /// completes when the attempt ends, with the outcome in <see cref="Status"/>.
    /// Concurrent calls share the one in-flight operation; a call after a
    /// finished attempt re-evaluates (retry after failure, cheap no-op once
    /// installed).
    /// </summary>
    public Task StartAsync(bool streamingEnabled, CancellationToken ct)
        => StartAsync(streamingEnabled, selectedModelName: null, ct);

    /// <summary>Begin or join. selectedModelName is the user's primary speech
    /// model (AppSettings.StreamingModelName); unknown/null falls back to the
    /// English default so upgrades never stall on a bad name.</summary>
    public Task StartAsync(bool streamingEnabled, string? selectedModelName, CancellationToken ct)
    {
        lock (_gate)
        {
            if (_current is { IsCompleted: false }) return _current;
            if (_status == StreamingAutoInstallStatus.Installed) return Task.CompletedTask;
            _current = RunAsync(streamingEnabled, selectedModelName, ct);
            return _current;
        }
    }

    private async Task RunAsync(bool streamingEnabled, string? selectedModelName, CancellationToken ct)
    {
        try
        {
            if (!streamingEnabled)
            {
                SetStatus(StreamingAutoInstallStatus.SkippedStreamingDisabled);
                return;
            }

            var descriptor =
                _registry.Find(selectedModelName ?? "") is { Kind: ModelKind.StreamingAsr } found
                    ? found
                    : _registry.Find(ModelRegistry.StreamingAsrName)!;

            if (IsInstalledAndExtracted(descriptor))
            {
                SetStatus(StreamingAutoInstallStatus.Installed);
                return;
            }

            SetStatus(StreamingAutoInstallStatus.Installing);
            await _operationGate.WaitAsync(ct).ConfigureAwait(false);
            try
            {
                await _downloader.DownloadAsync(descriptor, _installRoot, NullProgress.Instance, ct)
                    .ConfigureAwait(false);
            }
            finally
            {
                _operationGate.Release();
            }

            LastError = null;
            SetStatus(StreamingAutoInstallStatus.Installed);
        }
        catch (Exception ex)
        {
            LastError = ex.Message;
            SetStatus(StreamingAutoInstallStatus.Failed);
        }
    }

    /// <summary>Cheap per-launch health check: every file at its exact declared
    /// size, and every archive carrying a completed-extraction marker for its
    /// pinned SHA-256 plus the extracted tree.</summary>
    private bool IsInstalledAndExtracted(ModelDescriptor descriptor)
    {
        var modelDir = Path.Combine(_installRoot, descriptor.InstallDirRelative);
        foreach (var f in descriptor.Files)
        {
            var path = Path.Combine(modelDir, f.RelativePath);
            if (!File.Exists(path) || new FileInfo(path).Length != f.SizeBytes) return false;
            if (f.ExtractToRelative is { } extractTo &&
                !TarGzExtractor.IsExtracted(path, Path.Combine(modelDir, extractTo), f.Sha256))
            {
                return false;
            }
        }
        return true;
    }

    private void SetStatus(StreamingAutoInstallStatus status)
    {
        lock (_gate) _status = status;
        // Contain subscriber exceptions: StartAsync's never-throw contract
        // must hold mechanically, not depend on every subscriber behaving.
        // Status is already committed above, so observers via Status still
        // see the update.
        try { StatusChanged?.Invoke(this, status); }
        catch { /* subscriber fault must not fault the install */ }
    }

    private sealed class NullProgress : IProgress<DownloadProgress>
    {
        public static readonly NullProgress Instance = new();
        public void Report(DownloadProgress value) { }
    }
}

using Microsoft.Extensions.Logging.Abstractions;
using Shouldly;
using Winpepper.Platform.Hotkeys;
using Xunit;
using static Winpepper.Platform.Hotkeys.KeyboardHookNative;

namespace Winpepper.Platform.Tests.Hotkeys;

/// <summary>
/// A resume must leave NO half-tracked chord behind. Windows silently removes
/// the low-level hook across suspend/resume, so the transitions that would have
/// closed a chord (the key-ups) are simply never delivered; without a reset the
/// hook would think a chord is still held.
/// <para>
/// One case is NOT a silent drop: an ACTIVE hold owns an in-flight dictation,
/// so the reset must emit the terminating HoldUp itself - otherwise the session
/// never stops and every later press is swallowed by the engine's Idle guard.
/// </para>
/// </summary>
public class HotkeyHookReinstallTests
{
    private const int F24 = 0x87;

    private static HotkeyHook NewHook(string hold = "RightCtrl+RightShift",
                                      string toggle = "Ctrl+Shift+Space",
                                      string cancel = "Esc")
        => new(HotkeyChord.Parse(hold), HotkeyChord.Parse(toggle), HotkeyChord.Parse(cancel),
               new NullLogger<HotkeyHook>(),
               keyPhysicallyDown: _ => true);

    [Fact]
    public void Reinstall_During_A_Hold_Emits_Exactly_One_Terminating_HoldUp()
    {
        var hook = NewHook(hold: "F24");
        hook.TryProcessKey(F24, true, out var down).ShouldBeTrue();
        down!.Kind.ShouldBe(HotkeyEventKind.HoldDown);

        hook.RequestHookReinstall(); // system resumed mid-dictation

        // The reset MUST close the hold itself. The physical key-up that would
        // have ended this dictation was eaten by the suspend, so without this
        // event SessionEngine stays in Recording forever - mic open, buffer
        // growing, every later HoldDown dropped by the State != Idle guard.
        hook.Events.TryRead(out var terminating).ShouldBeTrue();
        terminating!.Kind.ShouldBe(HotkeyEventKind.HoldUp);

        // ...and exactly once: a late physical up finds no tracked hold, so it
        // is neither swallowed nor turned into a second HoldUp.
        hook.TryProcessKey(F24, false, out var up).ShouldBeFalse();
        up.ShouldBeNull();
        hook.Events.TryRead(out _).ShouldBeFalse();
    }

    [Fact]
    public void Reinstall_Clears_Modifier_State_So_A_HalfHeld_Chord_Cannot_Complete()
    {
        var hook = NewHook(); // hold = RightCtrl+RightShift
        hook.TryProcessKey(VK_RCONTROL, true, out var first).ShouldBeFalse();
        first.ShouldBeNull(); // chord incomplete so far

        hook.RequestHookReinstall();

        // Without the reset, RightCtrl would still be "held" and this would
        // complete the chord and fire HoldDown.
        hook.TryProcessKey(VK_RSHIFT, true, out var afterResume).ShouldBeFalse();
        afterResume.ShouldBeNull();
    }

    [Fact]
    public void Hook_Still_Works_After_Reinstall()
    {
        var hook = NewHook(hold: "F24", toggle: "F23");

        hook.RequestHookReinstall();

        // Nothing was held, so the reset must emit NOTHING: the terminating
        // HoldUp is for an interrupted hold only, never a blanket stop event.
        hook.Events.TryRead(out _).ShouldBeFalse();

        hook.TryProcessKey(F24, true, out var down).ShouldBeTrue();
        down!.Kind.ShouldBe(HotkeyEventKind.HoldDown);
        hook.TryProcessKey(F24, false, out var up).ShouldBeTrue();
        up!.Kind.ShouldBe(HotkeyEventKind.HoldUp);

        hook.TryProcessKey(0x86, true, out var toggle).ShouldBeTrue();
        toggle!.Kind.ShouldBe(HotkeyEventKind.Toggle);
    }

    [Fact]
    public void Reinstall_On_A_Never_Started_Hook_Is_Safe()
    {
        var hook = NewHook();

        Should.NotThrow(() => hook.RequestHookReinstall());
        Should.NotThrow(() => hook.Dispose());
    }
}

